ProjectALife.DialogueShards["scenes_any_32"] = {
{"s9_c02_mono_engine_two_012","any",1,"reg=rescue|role=rescue_firefighter|day=7,150|mood=calm|world=vehicle",{1,"Engine Two, I waxed you every Sunday for eleven years",1,"I don't lean on the siren like I used to. Can't help wondering what might come to it",1,"Still waxing you, somebody around here ought to look like a fire department"}},
{"s9_c02_mono_lamentations_013","any",1,"reg=rescue|role=rescue_clergy|day=3,150|hour=4,11|mood=sad",{1,"Brothers and sisters - no - friends, it's just friends now, whoever's left",1,"This morning's reading is from wherever this Bible falls open - it's been falling open to Lamentations",1,"I'm going to go ahead and pick a different page"}},
{"s9_c02_mono_eleven_names_014","any",1,"reg=rescue|role=rescue_clergy|tmp=seasoned|hour=20,2|mood=grim",{1,"Father, I have buried eleven people this week, and I said Your name over every one",1,"I want You to know I'm not angry with You",1,"I'm tired, there's a difference, and You know there is - goodnight"}},
{"s9_c02_mono_chief_complaint_friday_015","any",1,"reg=rescue|role=rescue_medical|mood=funny|world=road",{1,"Patient is a forty-one-year-old male - alert - Oriented - hungry",1,"Chief complaint, everything, relevant history, Friday",1,"Plan, sit down on this curb for five minutes - Transport, none available"}},
{"s9_c02_mono_smoke_garage_016","any",1,"reg=rescue|role=rescue_firefighter|tmp=seasoned|sex=m|day=10,150|mood=sad",{1,"Everything I own smells like smoke - always did - Sheila made me strip my gear off in the garage",1,"Came in from the Rosewood call today and stripped right there in her garage - force of habit",1,"Stood there in my shorts waiting on somebody to holler about the smell"}},
{"s9_c02_mono_mrs_durbin_017","any",1,"reg=rescue|role=rescue_medical|hour=21,3|mood=fear",{1,"If his fever's up in the morning, I tell his mother - straight, no maybe in it",1,"Mrs. Durbin, Caleb's fever is, Caleb has",1,"Okay, I'll say it in the morning - it could be down by morning"}},
{"s9_c02_mono_saltine_communion_018","any",1,"reg=rescue|role=rescue_clergy|day=10,150|mood=funny",{1,"Communion wafers ran out Sunday, it's saltines now - Unsalted, I'm not a heathen",1,"Asked forgiveness for the saltines, twice, to be safe",1,"Nobody's complained - old Mrs. Beeler would've complained, and she'd have been right"}},
{"s9_c02_mono_eulogy_folder_019","any",1,"reg=rescue|role=rescue_clergy|tmp=seasoned|mood=grim",{1,"Forty years, four hundred funerals, I kept a folder - farmer, veteran, child, drunk",1,"Mixed them and matched them, changed the names, nobody ever once caught me at it",1,"Can't use the folder now, nobody's dying of anything that's in the folder"}},
{"s9_c02_mono_attack_line_beans_020","any",1,"reg=rescue|role=rescue_firefighter|day=15,150|hour=6,10|mood=calm|world=fog",{1,"Chief would take my helmet for this, two hundred feet of attack line to water Mrs. Bell's pole beans",1,"Nozzle on wide fog - easy - easy - don't knock the blossoms off",1,"Beans don't care what the hose is rated for, neither do I, anymore"}},
{"s9_c02_strike_vote_001","any",2,"reg=worker|tmp=seasoned|mood=funny",{1,"Union meeting was set for the fourteenth, we had the votes",2,"We were gonna walk out",1,"Well, plant's shut down, every line, every shift",2,"Not how I pictured winning"}},
{"s9_c02_hay_company_002","any",2,"reg=worker,family|tmp=seasoned|day=5,60|mood=grim",{1,"First cutting's still laying in the Hagan field, got rained on twice",2,"Leave it",1,"Daddy never left hay down in a field in his whole life",2,"Daddy never had a field full of company"}},
{"s9_c02_canadian_quarter_003","any",2,"reg=worker|tmp=seasoned|day=3,120|mood=sad",{1,"Tip jar's still up by the register, eleven dollars and a Canadian quarter",2,"That quarter's Hank's, every Friday, same quarter, like I wouldn't notice",1,"You want to split it?",2,"You take the dollars, I'm keeping Hank's quarter"}},
{"s9_c02_brake_job_004","any",2,"reg=worker|mood=funny|world=door",{1,"Man dropped his truck off Thursday for brakes, said he'd be back Monday to pick it up",2,"He show?",1,"Showed up Tuesday, walked straight into the bay door - twice",2,"Well, now you know why he needed brakes"}},
{"s9_c02_biscuits_in_005","any",2,"reg=worker|tmp=seasoned|hour=16,21|mood=sad|world=vehicle,building",{1,"Used to key the truck radio ten minutes out so Pam could put the biscuits in",2,"Dispatch hated that",1,"Dispatch loved it, whole shop knew when Pam's biscuits went in the oven",2,"I'd key it for you, if you wanted",1,"Nah - leave the channel quiet"}},
{"s9_c02_school_slab_006","any",2,"reg=worker|tmp=seasoned|day=7,120|mood=sad|world=cars",{1,"We poured the slab for the Riverside elementary addition on the eighth - four trucks",2,"It's cured by now",1,"Forty feet of good slab with nothing on it, I finished that edge myself",2,"Kids would've had a real gym"}},
{"s9_c02_pink_copy_007","any",2,"reg=worker|tmp=seasoned|mood=funny",{1,"Foreman wrote me up Friday for being four minutes late off break",2,"Can't hold it against you now",1,"I got the pink copy folded in my wallet, when I see him, I'm handing it back",2,"What if he's one of them?",1,"Then I'll hand it back real fast"}},
{"s9_c02_sale_barn_cattle_008","any",2,"reg=worker|tmp=seasoned|day=5,90|mood=sad|world=fence,road",{1,"The Hagan cattle got through the fence, saw 'em walking the Dixie Highway in a line",2,"Headed where?",1,"Sale barn, if I had to guess, same road they went down every August on the trailer",2,"Somebody oughta turn 'em around",1,"And tell 'em what? They know that road better than we do"}},
{"s9_c02_distillery_bottle_009","any",2,"reg=worker|mood=funny",{1,"Twenty-six years at the distillery, and I never once took a bottle home",2,"And since Friday?",1,"Now I'm making up for lost time"}},
{"s9_c02_fire_lane_010","any",2,"reg=worker|tmp=seasoned|day=3,120|mood=sad|world=vehicle",{1,"Last thing Deb ever said over the plant intercom was, whoever's parked in the fire lane, move your vehicle",2,"Blue pickup, you know who you are",1,"That's the one, whole plant heard it",2,"Was it you?",1,"It was me, I never did move it"}},
{"s9_c02_water_tower_taps_011","any",2,"reg=worker|tmp=seasoned|day=2,30|mood=calm",{1,"Water tower's still got pressure on the east side of town",2,"How long's it hold?",1,"Gravity don't need a power plant, till it's empty - three weeks, if folks don't leave taps running",2,"Folks already are, half those houses got a tap open and nobody home",1,"Then we go shut 'em off, house by house - bring the big wrench"}},
{"s9_c02_shift_bell_012","any",2,"reg=worker|tmp=seasoned|hour=14,16|mood=funny|world=road",{1,"About shift-change time.. you feel that?",2,"Feel what?",1,"Shift change, my whole body wants to go stand in the parking lot and smoke",2,"You quit smoking in eighty-eight",1,"My body didn't get the memo, and it didn't quit the parking lot"}},
{"s9_c02_mittens_ladder_013","any",2,"reg=rescue|role=rescue_firefighter|day=3,90|hour=4,11|mood=warm|world=stairs,trees,road",{1,"Lady flagged us down on the Rosewood road this morning",2,"What'd she need?",1,"Cat up a tree",2,"Tell me you didn't run the ladder",1,"Whole county's falling in and I ran the ladder up for a cat named Mittens - best call I've had all month"}},
{"s9_c02_dry_collar_014","any",2,"reg=rescue|role=rescue_firefighter,rescue_medical|hour=5,9|mood=warm|world=building,rooftop,cold",{1,"Who hung my turnout coat by the stove?",2,"Not me, I was up on the roof all night",1,"It's bone dry, somebody scrubbed the collar out",2,"Still not me - put it on, it's cold this morning"}},
{"s9_c02_most_mornings_015","any",2,"reg=rescue|tmp=seasoned|mood=calm",{1,"Do you still believe, Father? Honest",2,"Most mornings",1,"And the rest of 'em?",2,"The rest I just do the work, and hope He's the kind that counts that"}},
{"s9_c02_doyle_test_016","any",2,"reg=rescue|role=rescue_medical|mood=funny",{1,"Clinic storeroom had a whole case of pregnancy tests, two hundred of 'em",2,"Useful",1,"Handed one to Doyle as a joke, he took it real serious",2,"What'd it say?",1,"He's not"}},
{"s9_c02_should_have_led_boat_017","any",2,"reg=rescue|role=rescue_firefighter|tmp=seasoned|mood=sad",{1,"You pray for Kenny?",2,"Offered the Lord my pension, my good knee, and the bass boat",1,"Any takers?",2,"Should've led with the boat - Kenny loved that boat"}},
{"s9_c02_somewhere_not_him_018","any",2,"reg=rescue|role=rescue_medical|tmp=seasoned|mood=funny",{1,"You told that man his leg is gonna be fine",2,"It is",1,"That leg is not gonna be fine",2,"It's gonna be fine somewhere, just not on him"}},
{"s9_c02_six_things_019","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|tmp=seasoned|mood=calm|world=building",{1,"Run bag gets six things, tourniquet, gauze, tape, shears, iodine, flashlight",2,"Blood pressure cuff?",1,"Out here the pressure's either there or it isn't - leave the cuff",2,"It's a good cuff",1,"Then hang it on the wall and look at it when you miss the hospital"}},
{"s9_c02_shared_shovel_020","any",2,"reg=rescue|role=rescue_clergy|mood=funny",{1,"The Baptist preacher and I buried two out behind the feed store today - shared a shovel",2,"Ecumenical",1,"He dug - I prayed, he says next time the Methodist digs",2,"You gonna dig next time?",1,"I told him we'll pray on it"}},
{"s9_c02_eat_first_captain_021","any",2,"reg=rescue|role=rescue_firefighter|tmp=seasoned|mood=warm|world=building",{1,"You'd have liked our old captain",2,"That right?",1,"He'd have made you eat before he let you tell him one thing - didn't matter if the roof was coming in",2,"Sounds like my mother",1,"Sounds like everybody that was ever worth a damn"}},
{"s9_c02_lipstick_rosary_022","any",2,"reg=rescue|role=rescue_medical,rescue_clergy|mood=sad",{1,"Mrs. Priddy asked for two things, her rosary and her lipstick",2,"Lipstick?",1,"Said she wasn't about to meet Jesus looking like this",2,"Did you find it?",1,"In her purse - Coral, I put it on her myself, stayed inside the lines, too"}},
{"s9_c02_waiting_room_quiz_023","any",2,"reg=rescue|mood=funny",{1,"Clinic waiting room magazine from nineteen eighty-seven, somebody filled out half the quiz",2,"Which quiz?",1,"Is Your Marriage in Trouble, she quit at question nine - do you and your spouse argue about money?",2,"Well, that one's sorted out now"}},
{"s9_c02_ring_the_rest_024","any",2,"reg=rescue|role=rescue_clergy|tmp=seasoned|day=7,150|mood=warm",{1,"I rang the bell once for every name on the list",2,"How many'd you get to?",1,"Thirty, my arm quit on me at thirty",2,"Where's the list? I'll ring the rest"}},
{"s9_c03_mono_marla_backup_001","any",1,"reg=law|tmp=seasoned,veteran|sex=m|hour=19,1|mood=sad",{1,"Marla, I did the thing you hated, went in the Tolliver house without backup",1,"Came out fine - don't make that face at me",1,"I know you can't make any face, I make it for you, every time I go in anywhere"}},
{"s9_c03_mono_courthouse_clock_002","any",1,"reg=law|role=law_sheriff,law_sergeant,law_deputy|day=5,150|mood=funny",{1,"Courthouse clock stopped at ten after four, nobody left who knows how to wind it",1,"Judge Cundiff set his watch by that clock every morning for thirty years - swore it was never off a minute",1,"Well, it's right twice a day now, that's better than most of this county"}},
{"s9_c03_mono_remain_silent_003","any",1,"reg=law|tmp=seasoned,veteran|day=5,150|mood=funny",{1,"You have the right to remain silent",1,"And every one of you has been real good about that part - I'll give you that",1,"Anything you say can and will be used against you - moaning don't count, I'll let the moaning slide"}},
{"s9_c03_mono_checkers_owed_004","any",1,"reg=law|role=law_corrections|hour=20,2|mood=sad",{1,"Lord, I can't tell You half those men deserved mercy - deciding that was never my job",1,"My job was the count, make sure everybody's where they're supposed to be",1,"So if You're doing a count up there, look for Leroy Goff - he owes me a checkers game"}},
{"s9_c03_mono_pepper_rides_005","any",1,"reg=law|role=law_deputy,law_officer,law_trooper|day=4,150|mood=warm",{1,"You ride up front, you don't touch the radio, you don't eat the seat - those are the rules",1,"You got no badge - no academy - no sense, you're the best partner I've had all week",1,"That's a real low bar, Pepper - don't let it go to your head"}},
{"s9_c03_mono_roadway_maam_006","any",1,"reg=law|tmp=seasoned,veteran|mood=grim|world=road",{1,"Ma'am, you're walking in the roadway",1,"Ma'am - Ma'am, I need you to stop right there and show me your hands",1,"Okay, okay, ma'am - we're gonna call that resisting"}},
{"s9_c03_mono_only_name_ballot_007","any",1,"reg=law|role=law_sheriff|day=10,200|mood=funny",{1,"Re-elect Wade Cundiff for Sheriff, nineteen years of service, and I'll still be here next year",1,"Probably be the only name on the ballot, too",1,"Might be the only voter - well, I know how I'm voting"}},
{"s9_c03_mono_b_in_math_008","any",1,"reg=law|role=law_corrections,law_officer,law_deputy|sex=m|day=3,90|hour=16,5|mood=sad",{1,"Envelope from Dennis's school came Thursday before all this, never opened it",1,"Opened it tonight - report card - B in math",1,"B in math, Dennis, first B you ever got in math - I'm putting it up on the dash"}},
{"s9_c03_mono_every_pothole_009","any",1,"reg=law|role=law_trooper|day=5,150|hour=4,11|mood=calm|world=vehicle,window,road",{1,"Ninety-two miles of state road in my district, I knew every pothole by the sound it made under the car",1,"Drove it this morning with the windows down, didn't meet a single car - not one",1,"Hit every pothole anyhow, out of respect"}},
{"s9_c03_mono_emergency_traffic_010","any",1,"reg=law|role=law_officer,law_deputy|tmp=seasoned|mood=fear",{1,"Never prayed on duty, figured the Lord didn't need my radio traffic",1,"Break, break - emergency traffic, that's what this is, Lord",1,"Keep my sister in Valley Station, that's all I got - clear"}},
{"s9_c03_mono_no_pulse_011","any",1,"reg=law|role=law_deputy,law_officer|tmp=seasoned|mood=funny",{1,"Sat in this speed trap behind the church sign six years - folks knew - they'd wave",1,"Only thing coming through now does about two miles an hour",1,"I'd write it up, but it's got no license, no insurance, and no pulse"}},
{"s9_c03_mono_announce_elm_012","any",1,"reg=law|role=law_deputy,law_sheriff|day=3,60|mood=grim|world=door",{1,"Academy said announce yourself at the door, sheriff's office, come to the door",1,"Said it at every house on Elm Street today, out of habit, good and loud, like they taught us",1,"Thing is, it works, every one of 'em comes to the door"}},
{"s9_c03_mono_cut_it_tonight_013","any",1,"reg=law,swat|sex=f|day=2,60|hour=16,5|mood=fear",{1,"Hair up under the hat - sleeves down - gloves on, nothing for 'em to grab",1,"Cutting it tonight, all of it, should've done it the first day",1,"Mama's gonna kill me - heh, mama's gonna kill me"}},
{"s9_c03_mono_eight_seats_014","any",1,"reg=swat|day=3,120|mood=sad|world=vehicle",{1,"Van's got eight seats, rode out with eight on Friday",1,"Rode back with three, names are still on the tape over every seat",1,"Nobody sits under Ricky's name, we put the ammo cans there - Ricky'd like that fine"}},
{"s9_c03_mono_easy_house_015","any",1,"reg=swat|role=swat_lead|mood=grim|world=door,building",{1,"Easy house, that's what we'd have called this one - two doors, one hallway, no dogs",1,"Ain't no easy houses anymore, every house has a family in it that didn't leave",1,"Stack up, Harlan, you're talking to yourself again, Harlan - stack up"}},
{"s9_c03_mono_oral_board_016","any",1,"reg=swat|role=swat_operator|mood=funny",{1,"Eighteen months on the waiting list for this team - written test - PT test - Oral board",1,"Board asked me what I'd do with a barricaded subject and hostages - I had a real good answer",1,"Nobody on that board asked about any of this, I'd have flunked this part"}},
{"s9_c03_mono_grain_elevator_017","any",1,"reg=swat|role=swat_operator|hour=6,11|mood=warm",{1,"Grain dust in everything up here - scope - bolt - teeth",1,"Four hundred yards of Main Street, and nothing moves on it I don't see",1,"Mrs. Hale walked her dog past the bank at seven - she doesn't know I'm up here, nobody tell her"}},
{"s9_c03_mono_hands_first_018","any",1,"reg=swat|hour=3,6|mood=calm",{1,"Lord, keep my hands steady and my feet dry",1,"And if You can only do the one, just the hands - I'll live with wet socks"}},
{"s9_c03_mono_arm_off_table_019","any",1,"reg=swat|tmp=veteran|mood=funny|world=vehicle",{1,"This is the Knox County negotiator - come out with your hands where I can see them",1,"No? Okay, what do you want? A car? A pizza? Somebody's arm?",1,"We can't do the arm, the arm is off the table"}},
{"s9_c03_evidence_locker_001","any",2,"reg=law|mood=funny",{1,"We still got forty pounds of seized marijuana in the evidence room",2,"Sheriff says it's county property, nobody touches it",1,"Then why's he got it signed out on the log?",2,"Says he's keeping it safe till court reconvenes",1,"Court's not reconvening",2,"Then it's gonna be real safe"}},
{"s9_c03_glove_on_dash_002","any",2,"reg=law|tmp=seasoned|day=2,40|mood=sad|world=vehicle",{1,"Told Kaylee I'd make her tournament in Brandenburg - Saturday, ten o'clock, swore on my badge",2,"They'd have called it off anyway",1,"Her glove's still on my dashboard, she left it in the car Thursday",2,"Then that's where it rides"}},
{"s9_c03_pharmacy_names_003","any",2,"reg=law|tmp=seasoned,veteran|day=2,30|mood=grim",{1,"Looters in the pharmacy on Main, four of 'em",2,"Arrest 'em?",1,"And put 'em in what jail? Write the names down and send 'em home",2,"And if what they're carrying out is insulin?",1,"Then I didn't see 'em at all, and neither did you"}},
{"s9_c03_right_to_be_scared_004","any",2,"reg=law|role=law_trooper,law_deputy|tmp=seasoned,veteran|mood=sad",{1,"Told my brother he was a coward for staying home when they called for volunteers on the line",2,"He was scared",1,"He was, and he was right to be, I'd like to tell him that part"}},
{"s9_c03_chief_citation_005","any",2,"reg=law|role=law_officer,law_sergeant|hour=4,11|mood=funny",{1,"Chief says we still write speeding tickets, keeps up the standard",2,"For who? Nobody's driving",1,"He wrote one this morning",2,"Who'd he get?",1,"Me, forty-one in a twenty-five, running from the school"}},
{"s9_c03_pickled_eggs_006","any",2,"reg=law|day=3,90|mood=warm",{1,"Mrs. Heady walked a gallon jar of pickled eggs out to the roadblock",2,"Walked? She's eighty if she's a day",1,"Four miles, said the county never did pay us enough",2,"She's not wrong",1,"Don't tell her that, she'll walk out another jar"}},
{"s9_c03_you_flinch_after_007","any",2,"reg=swat|tmp=veteran|mood=grim",{1,"If I turn, you do it - not Jenkins - Jenkins flinches",2,"I flinch too",1,"You flinch after, that's the difference"}},
{"s9_c03_owes_one_door_008","any",2,"reg=swat|day=3,120|mood=funny|world=door",{1,"Old man in March Ridge wants the county to pay for his front door",2,"We saved his life going through that door",1,"He agrees, he still wants the door",2,"Write him something",1,"Wrote it on a napkin - Knox County SWAT owes one door, he folded it up and put it in his Bible"}},
{"s9_c03_taxes_went_009","any",2,"reg=law|tmp=seasoned,veteran|day=4,120|mood=warm|world=cars",{1,"Farmer out past Ekron let us fill both cruisers off his diesel tank - wouldn't take the county voucher",2,"He say why?",1,"Said he's paid taxes forty years, and this is the first time he got to see where it went"}},
{"s9_c03_reference_letter_010","any",2,"reg=law|role=law_corrections|mood=funny",{1,"One of the men we let walk asked me for a reference letter",2,"For what job?",1,"Said whoever's hiring, so I wrote one, shows up on time, stays where you put him",2,"That's a good reference",1,"Best one I ever wrote, seven years of research went into it"}},
{"s9_c03_cut_from_inside_011","any",2,"reg=law|tmp=seasoned|day=3,60|mood=sad|world=door",{1,"Found Kessinger's cruiser nose down in Otter Creek, driver door open",2,"Him?",1,"Hat on the seat - seatbelt cut",2,"Cut?",1,"Cut from the inside, with his knife, he got himself out - that's what I'm going with"}},
{"s9_c03_screen_door_ram_012","any",2,"reg=swat|day=5,150|mood=sad|world=door",{1,"Remember when Donnie took the ram to that screen door in Radcliff?",2,"Went right through it, came out the other side wearing the whole frame - heh",1,"Walked around the yard in it like a picture frame, hollering for somebody to take his picture - he, uh",2,"Yeah"}},
{"s9_c03_who_takes_badge_013","any",2,"reg=law|day=10,200|mood=sad",{1,"Kid at the church asked me am I still a cop if nobody pays me",2,"And you said what?",1,"Said I'm a cop till somebody takes the badge",2,"Good answer",1,"He asked me who's left to take it, I didn't have one for that"}},
{"s9_c03_pistol_goes_point_014","any",2,"reg=law,swat|tmp=veteran,seasoned|day=15,200|mood=calm",{1,"If we were down to a few rounds, how would you decide who carried them?",2,"Rank, or who needs them?",1,"I'd check which weapon they actually fit, then who could use it safely. Not who had the stripes",2,"Sergeant's not gonna like that",1,"Neither would I, if I was the sergeant. Doesn't make rank a substitute for checking"}},
{"s9_c03_ten_ninety_nine_015","any",2,"reg=law|day=5,150|mood=funny",{1,"Unit 12 to anybody, I'm 10-7 for lunch",2,"Nobody's on the air to tell, Doug",1,"I'm telling the air, then, air ought to know where I eat",2,"What's for lunch?",1,"Cold pork and beans out of the can, at the Ekron crossroads, if the air's taking notes"}},
{"s9_c03_nameplate_chair_016","any",2,"reg=law|role=law_sheriff,law_sergeant,law_deputy|tmp=veteran,seasoned|hour=4,11|mood=grim",{1,"State says a county with no sheriff reverts to the coroner",2,"Coroner's been dead since Saturday",1,"Then after the coroner it's the county judge",2,"He's on his roof with a deer rifle, and he says he resigns",1,"So it's us - put the coffee on, we're the Commonwealth this morning"}},
{"s9_c03_flag_half_staff_017","any",2,"reg=law|day=3,60|hour=6,10|mood=sad",{1,"Who lowered the flag at the station?",2,"I did - half staff",1,"For who?",2,"Pick one, I'll leave it there till we run out of ones to pick"}},
{"s9_c03_sheriffs_hat_fits_018","any",2,"reg=law|tmp=seasoned|day=10,150|mood=funny",{1,"You're wearing the sheriff's hat",2,"It fit",1,"That's not how succession works",2,"Show me the part of the Kentucky Revised Statutes about hats",1,"Take it off before somebody salutes you"}},
{"s9_c03_miranda_card_kid_019","any",2,"reg=law|day=5,150|mood=warm",{1,"A little girl once handed me a crayon picture",2,"Of you?",1,"Hat and all. Gave me six arms",2,"Maybe she thought that's how many you'd need for all this"}},
{"s9_c03_scanner_grandpa_020","any",2,"reg=law|hour=20,2|mood=sad",{1,"Somebody on a scanner keeps keying in on our channel every night about eleven - just static",2,"Could be anybody",1,"It's Mr. Tipton, he bought a scanner so he could hear his grandson on the radio",2,"His grandson's Wes",1,"I know who his grandson is, I say goodnight on the air at eleven, unit 7, clear, like Wes did"}},
{"s9_c03_swat_gas_mask_021","any",2,"reg=swat|mood=funny|world=building",{1,"Ever want to wear a gas mask to supper?",2,"After four days in a basement with my old squad, yes",1,"I'd have wanted a spare too"}},
{"s9_c03_stack_of_two_022","any",2,"reg=swat|tmp=veteran|day=10,200|mood=grim",{1,"Stack of two, you're number one - I'm number two",2,"We used to call a stack of two a mistake",1,"We used to have eight - go on the squeeze"}},
{"s9_c03_lieutenant_polish_023","any",2,"reg=law|role=law_trooper|mood=warm|world=building",{1,"Why are you shining your boots? Nobody's inspecting",2,"My daddy was a trooper - Shined 'em every night of my life at the kitchen table",1,"And?",2,"And if I quit shining 'em, then something's over, I'm not ready for it to be over"}},
{"s9_c03_polite_drunk_024","any",2,"reg=law|role=law_officer,law_deputy|hour=21,3|mood=funny|world=window",{1,"Arrested Jimmy Beeler for public intoxication tonight, out of habit",2,"Where's Jimmy at now?",1,"Back seat, windows up, he's sleeping it off safer than anybody in the county",2,"He thank you?",1,"Asked could he get arrested again tomorrow"}},
{"s9_c04_mono_sunday_call_001","any",1,"reg=military|role=soldier,soldier_green|sex=m|day=3,45|hour=21,2|mood=sad",{1,"Hey, Tina, I know I said I'd call Sunday",1,"Phones are down, that's the truth, you can ask anybody on this line",1,"You can't ask anybody, I know that - I'm just, I'm sorry about Sunday"}},
{"s9_c04_mono_front_latrine_002","any",1,"reg=military|role=soldier_nco|tmp=veteran|mood=funny|world=cold",{1,"Twenty-two years - Panama - the Gulf, two winters in Germany freezing my tail off",1,"Always knew where the front was, you pointed your rifle at it and you went to sleep with your back to the other way",1,"Front's everywhere now - front's in the latrine, front was in the chow line Tuesday"}},
{"s9_c04_mono_quiet_prayer_003","any",1,"reg=military|role=soldier_green|hour=21,4|mood=fear",{1,"Our Father, who art, who art in heaven",1,"Drill sergeant says prayer is a personal matter and to do it quietly",1,"This is me being quiet, God, I'm real scared - amen, I guess"}},
{"s9_c04_mono_charge_of_cow_004","any",1,"reg=military|role=soldier,soldier_green|hour=0,5|mood=funny|world=fence",{1,"General order number one - take charge of this post and all government property in view",1,"Government property in view - one fence, one Humvee with a flat, one dead cow",1,"Cow's not government property, I'm taking charge of it anyway - nobody's touching my cow"}},
{"s9_c04_mono_half_for_cruz_005","any",1,"reg=military|tmp=seasoned|day=7,90|hour=16,5|mood=sad",{1,"Still break my crackers in two, half for Cruz",1,"Cruz hated the vegetable crackers, took his half every time anyhow, said it'd hurt my feelings",1,"Ate both halves tonight, tasted like cardboard, tasted like his half"}},
{"s9_c04_mono_private_dunn_006","any",1,"reg=military|role=soldier_green|day=2,20|mood=fear",{1,"Any station, this is Private Dunn, I don't know my callsign - Sergeant had it written on his arm",1,"I'm at the Rosewood fire station with two civilians and one rifle - over",1,"Please somebody just say over back - over"}},
{"s9_c04_mono_flare_name_tape_007","any",1,"reg=military|tmp=seasoned,veteran|hour=21,4|mood=grim",{1,"Flare's up - count 'em, nine in the bean field",1,"Ten - eleven, the eleventh one's in a uniform like mine",1,"Don't look at the name tape, don't read it - front sight, and squeeze"}},
{"s9_c04_mono_mail_under_pillows_008","any",1,"reg=military|role=soldier,soldier_nco|day=5,60|hour=16,5|mood=sad",{1,"Mail sack from the Thursday before, sat in the orderly room this whole time - nobody sorted it",1,"Sorted it tonight - put everybody's letters on their cots",1,"Some cots, I put the letter up under the pillow - seemed more private"}},
{"s9_c04_mono_college_money_009","any",1,"reg=military|role=soldier_green|mood=funny",{1,"Recruiter said two years, see the world, money for college",1,"I've seen forty miles of the world, my mama's house in Radcliff is right over that ridge",1,"College better be real good"}},
{"s9_c04_mono_one_you_hear_010","any",1,"reg=military|role=soldier_green,soldier|hour=22,4|mood=fear",{1,"Sergeant says you never hear the one that gets you",1,"So every one I can hear out there is one that's not getting me",1,"That's a whole lot of good news out there tonight"}},
{"s9_c04_mono_powder_blue_011","any",1,"reg=military|role=soldier,soldier_green|day=5,120|mood=funny",{1,"Somebody pinned my prom picture on the orderly room bulletin board - powder blue tux - ruffles",1,"Building's half burned, that board's the only wall still standing",1,"Powder blue ruffles, outlasting the end of the world, course it did"}},
{"s9_c04_mono_no_preference_012","any",1,"reg=elite|tmp=veteran|hour=22,4|mood=calm",{1,"Not a praying man, checked the box on my enlistment form",1,"Box said No Preference",1,"Put me down as a preference tonight - just tonight"}},
{"s9_c04_mono_short_drive_013","any",1,"reg=elite|tmp=veteran|sex=m|day=10,200|mood=funny|world=road",{1,"Told Jeanie this was my last deployment - promised her",1,"Short drive, I said, two hours down the road to Knox - home by the weekend",1,"Still true, technically, real short drive - real long weekend"}},
{"s9_c04_mono_was_a_mailman_014","any",1,"reg=elite|tmp=veteran|mood=grim",{1,"Wind left to right - two minutes - hold one mil",1,"Target's a mailman, satchel and all",1,"Was a mailman - sending"}},
{"s9_c04_mono_painted_rock_015","any",1,"reg=elite|tmp=veteran|day=5,200|mood=warm",{1,"Kid at the Muldraugh overpass asked if I was Army",1,"Told him no, told him I'm nobody",1,"Kid said okay, nobody, thank you, handed me a rock with a smiley face painted on it",1,"Rock's in my left cargo pocket, team doesn't need to know about the rock"}},
{"s9_c04_mono_rule_three_016","any",1,"reg=elite|tmp=veteran|hour=20,4|mood=funny",{1,"Rules for tonight - no light - no fire - no talking",1,"Broke rule three",1,"Just now - logging it"}},
{"s9_c04_mono_transparent_apple_017","any",1,"reg=elite|tmp=veteran|day=3,40|hour=9,17|mood=calm|world=trees",{1,"Yellow apple tree behind the Methodist church - early kind, picked one standing in the ditch",1,"Sour enough to turn my face inside out, juice all down my sleeve, every fly in the county found me",1,"Worth it, that doesn't go in the report"}},
{"s9_c04_mono_never_during_018","any",1,"reg=elite|tmp=veteran|mood=calm",{1,"Hands shake after - never during, twenty years, never once during",1,"Sit on them, count to sixty, then stand up",1,"Fifty-nine - sixty - standing up"}},
{"s9_c04_plan_a_faster_001","any",2,"reg=military|mood=funny",{1,"Sergeant, what's the plan if the plan doesn't work?",2,"Plan B",1,"What's Plan B, Sergeant?",2,"Plan A. Faster"}},
{"s9_c04_hollering_radio_002","any",2,"reg=military|tmp=seasoned|day=2,60|mood=sad|world=water",{1,"How'd you get those kids across the creek with forty of them in the yard?",2,"Lopez took the radio and walked out into the soybeans hollering into it - loud as he could",1,"And they followed the hollering",2,"I took the kids across the creek, like he told me"}},
{"s9_c04_family_day_chicken_003","any",2,"reg=military|role=soldier,soldier_green|day=3,60|mood=sad",{1,"Family day was July third - Mom brought fried chicken in a cooler out to the parade field",2,"Your little brother come?",1,"Wore my patrol cap all day, down over his eyes, wouldn't give it back at the gate",1,"That was Saturday"}},
{"s9_c04_captain_hand_004","any",2,"reg=military|tmp=seasoned,veteran|mood=grim",{1,"Captain asked who'd take post one at the school tomorrow - nobody put a hand up",2,"What'd he do?",1,"Put his own hand up",2,"The Captain did?",1,"The Captain did, then six more hands went up"}},
{"s9_c04_late_formation_005","any",2,"reg=military|tmp=seasoned|day=4,90|mood=sad",{1,"Nobody saw what happened to Sergeant Vance after the bridge",2,"So he's missing, that's how it goes on the report",1,"I wrote him down late for formation",2,"That's a paperwork violation",1,"Then court-martial me - he's late"}},
{"s9_c04_bug_spray_chaplain_006","any",2,"reg=military|mood=funny",{1,"Good news, battalion's sending a resupply",2,"What's the bad news?",1,"It's a pallet of bug spray and a chaplain",2,"What's the chaplain for?",1,"For when the bug spray doesn't work"}},
{"s9_c04_loyal_goat_007","any",2,"reg=military|mood=funny",{1,"Private, why is there a goat in my Humvee?",2,"She followed me, Sergeant",1,"Followed you from where?",2,"Brandenburg, Sergeant",1,"That's eleven miles",2,"She's very loyal, Sergeant"}},
{"s9_c04_departed_where_008","any",2,"reg=military|tmp=seasoned,veteran|day=5,120|mood=grim",{1,"Sergeant, what do I put on the sign-out sheet for Hollins?",2,"Write departed",1,"Departed where?",2,"Just departed - let whoever reads it next worry about where"}},
{"s9_c04_coffee_with_ideas_009","any",2,"reg=military|tmp=seasoned|day=5,120|hour=5,9|mood=sad",{1,"I remember hearing we'd lost Specialist Ruiz at the Salt River bridge",1,"I tried changing the subject. Asked if your coffee was hot water with ideas",2,"It was. We both knew what you didn't want to talk about"}},
{"s9_c04_camo_ammo_010","any",2,"reg=military|mood=funny",{1,"Base, this is Two-Two, we need more ammo, over",2,"Two-Two, say again, over",1,"AMMO, we need AMMO - over",2,"Copy, more camo - wilco - out",1,"Great, they'll never see us die"}},
{"s9_c04_shoe_polish_face_011","any",2,"reg=military|role=soldier_green|mood=funny",{1,"Why is your face black, Private?",2,"Camouflage, Sergeant, no face paint left, so I used boot polish",1,"You look like a raccoon that fell in a tar pit",2,"Invisible raccoon, Sergeant"}},
{"s9_c04_mess_hall_birthday_012","any",2,"reg=military|day=3,90|mood=warm",{1,"Cook found one can of frosting in the mess hall storeroom - chocolate",2,"For what?",1,"Put it on crackers for Pruett's birthday, wrote a two and a zero on it with a knife",2,"He's twenty?",1,"Twenty today, cried in front of the whole platoon - nobody said one word to him about it"}},
{"s9_c04_twenty_questions_013","any",2,"reg=military|hour=1,5|mood=fear",{1,"Twenty questions, I'm thinking of something",2,"Is it bigger than a breadbox?",1,"Yeah",2,"Is it out there past the wire right now?",1,"Don't do that, ask a regular question"}},
{"s9_c04_schedule_guys_014","any",2,"reg=elite|tmp=veteran|day=5,200|mood=funny",{1,"Local asked me if we're the good guys",2,"What'd you say?",1,"Said we're the ones with a schedule"}},
{"s9_c04_gave_back_picture_015","any",2,"reg=elite|tmp=veteran|day=3,90|mood=sad",{1,"Boy in Rosewood asked me to find his mama, gave me her picture out of his wallet",2,"Did you?",1,"Found her on Main Street, by the bank",2,"And?",1,"Gave him back the picture, told him I looked everywhere and didn't find her"}},
{"s9_c04_thirty_one_years_016","any",2,"reg=elite|tmp=veteran|mood=grim",{1,"He asked me to do it before he turned",2,"You ask him did he want a minute?",1,"I asked, he said he'd had thirty-one years, and that was plenty of minutes"}},
{"s9_c04_he_had_brothers_017","any",2,"reg=elite|tmp=veteran|mood=warm",{1,"You gave that kid your last ration",2,"Gave him the cracker",1,"The whole bag's gone",2,"He had brothers"}},
{"s9_c04_militia_lesson_018","any",2,"reg=elite|tmp=veteran|day=10,200|mood=funny",{1,"Local militia asked us to teach them some tactics",2,"What'd you teach them?",1,"Don't stand in front of the man with the rifle",2,"That's lesson one",1,"Took all afternoon"}},
{"s9_c04_hold_mother_019","any",2,"reg=elite|tmp=veteran|mood=grim",{1,"Wind?",2,"Left to right - light",1,"Target",2,"Woman by the swing set - she's turned, boy about ten is holding her hand",1,"Hold",2,"Holding"}},
{"s9_c05_mono_let_daddy_say_001","any",1,"reg=outlaw|role=deserter|day=3,90|mood=sad|world=vehicle,fence",{1,"Mama, I walked off the line, I know what Daddy would say about it",1,"Daddy never stood a fence at two in the morning and watched a school bus come at it",1,"So he can say it, I'll stand right here and let him say every word"}},
{"s9_c05_mono_wanted_poster_002","any",1,"reg=outlaw|role=outlaw|day=5,150|mood=funny|world=building",{1,"Irvington post office still has my picture on the wall - wanted for questioning - nineteen eighty-nine",1,"Nobody's got questions for anybody anymore, not a single question left in this county",1,"Took it down, it's a real good picture of me, honestly - keeping it"}},
{"s9_c05_mono_half_even_003","any",1,"reg=outlaw|tmp=seasoned|hour=20,3|mood=funny",{1,"I robbed a church once - don't act like You don't remember",1,"Gave half of it back, the half I didn't drink",1,"So I figure we're half even, I'm asking for the other half on credit"}},
{"s9_c05_mono_service_number_004","any",1,"reg=outlaw|role=deserter|mood=grim",{1,"Name, rank, service number, still say it in my head every time I walk",1,"Name's still mine - Rank's gone, walked off with the rest of it",1,"Number I can't shake, left foot, right foot, the same nine numbers - quit it"}},
{"s9_c05_mono_sonny_lighter_005","any",1,"reg=outlaw|tmp=seasoned|mood=grim",{1,"Dug you a hole, Sonny - shallow one, you'd have dug me worse",1,"I'm keeping your lighter, you'd have kept my boots before I was cold",1,"Fair's fair - heh, first fair thing between us in twelve years"}},
{"s9_c05_mono_nobody_bothering_006","any",1,"reg=outlaw|role=outlaw|day=10,200|mood=funny|world=road",{1,"Lived up this holler forty years so nobody would come bother me",1,"World ended, still nobody bothering me - not one soul up that road since June",1,"Tell the truth, I figured I'd enjoy it more"}},
{"s9_c05_mono_lousy_with_kids_007","any",1,"reg=raider|tmp=predator|mood=angry",{1,"Please, please, I got kids, everybody's got kids",1,"Kids in Brandenburg, kids in Rosewood - whole county's lousy with kids",1,"Nobody out here's got a spare can of gas, though - just kids"}},
{"s9_c05_mono_kings_eat_008","any",1,"reg=raider|role=raider|hour=19,23|mood=funny",{1,"Boss says we're the kings of Knox County now, says kings eat good",1,"King had a can of dog food for supper - warm",1,"Next house we hit, I'm taking the dog, the dog's eating better than the king"}},
{"s9_c05_mono_good_jam_009","any",1,"reg=raider|tmp=predator,seasoned|hour=21,3|mood=sad",{1,"That old lady looked at me like my mama used to look at me",1,"Took her pantry anyway, took the good jam, blackberry, with her name wrote on the lid",1,"Can't eat it, it just sits in my pack looking at me"}},
{"s9_c05_mono_whole_speech_010","any",1,"reg=raider|role=raider|mood=funny|world=generator",{1,"Your money or your life - no, nobody's got money",1,"Your food or your life, your gas or your life, your, uh, generator or your life",1,"Your stuff, just give me your stuff - that's the speech, that's all I got"}},
{"s9_c05_mono_knox_navy_011","any",1,"reg=raider|tmp=predator|day=5,150|mood=funny",{1,"Always wanted a boat, took one today off a man at Fallas Lake - bass boat - Sparkly paint",1,"Don't know how to drive a boat, sat in it on the trailer and ate Vienna sausages",1,"Admiral of the Knox County Navy, parked in a gravel lot"}},
{"s9_c05_mono_youth_group_012","any",1,"reg=gang|role=gang_member|day=3,90|hour=16,22|mood=funny",{1,"Good evening, ma'am - no - evening, ma'am, we're a, uh, youth group",1,"Youth group from Louisville, on a mission trip - we're real sorry about the tattoos",1,"Mission's to not get shot by church folks, that part's true, at least"}},
{"s9_c05_mono_which_rule_013","any",1,"reg=gang|role=gang_boss|mood=grim",{1,"Three rules, nobody touches the kids - nobody touches the water - nobody runs",1,"Kid ran last night, took both water jugs with him",1,"So tell me which rule I get to break"}},
{"s9_c05_mono_kentucky_lucky_014","any",1,"reg=gang|tmp=predator,seasoned|day=5,150|mood=sad|world=vehicle",{1,"Lil Tone used to rap on the back of the bus - worst rhymes on Broadway",1,"Rhymed Kentucky with lucky in every single song - every one - heh, last one he did, he",1,"Whatever, pass me the water"}},
{"s9_c05_mono_sunrise_on_purpose_015","any",1,"reg=gang|hour=5,8|mood=warm|world=water,fog",{1,"Never watched the sun come up on purpose, only ever saw it coming home",1,"Watched it this morning over the creek bottoms, fog and everything - birds going off",1,"Ain't telling nobody, crew would never let me live it down"}},
{"s9_c05_little_league_name_001","any",2,"reg=raider|tmp=predator|mood=funny",{1,"Boss wants us to call ourselves something, something with teeth in it",2,"Like what?",1,"The Ekron Wolves",2,"We're from Irvington",1,"The Irvington Wolves, then",2,"Sounds like a Little League team, my nephew played for the Irvington Wolves"}},
{"s9_c05_tell_his_wife_002","any",2,"reg=raider|tmp=predator,seasoned|mood=sad",{1,"Man we tied up at the bait shop asked me to tell his wife he wasn't scared",2,"You gonna?",1,"Don't know his wife, don't know her name - don't know where she's at",2,"Then tell me",1,"He wasn't scared"}},
}
